// This file is generated by AI.

// 重命名编辑的应用: LSP 的 UTF-16 行列 -> 文本替换。
// 只做纯计算 (不依赖编辑器与应用状态), 便于单测。

import { fromUri } from '../lib/uri';
import type { LspPosition, LspRange, LspTextEdit, LspWorkspaceEdit } from './client';

/** 单个文件上的重命名编辑 */
export interface RenameFileEdit {
  /** 项目内文件路径 */
  path: string;
  edits: LspTextEdit[];
}

/** 单个待应用的替换 (文本下标) */
interface Replacement {
  start: number;
  end: number;
  text: string;
}

/** LSP 位置 (行列, UTF-16) -> 文本下标 */
export function offsetAt(text: string, position: LspPosition): number {
  let offset = 0;
  for (let line = 0; line < position.line; line += 1) {
    const next = text.indexOf('\n', offset);
    if (next < 0) return text.length;
    offset = next + 1;
  }
  return offset + position.character;
}

/** 把区间换算成替换 (基于原文, 因此可安全地从后往前应用) */
function replacementAt(text: string, range: LspRange, value: string): Replacement {
  return {
    start: offsetAt(text, range.start),
    end: offsetAt(text, range.end),
    text: value,
  };
}

/**
 * 应用一组文本编辑。
 *
 * 编辑的区间基于**原文** (LSP 约定), 因此先全部换算成下标, 再从后往前替换 —— 这样前面的
 * 下标不会因为后面的替换而失效。
 */
export function applyTextEdits(text: string, edits: LspTextEdit[]): string {
  const replacements = edits
    .map((edit) => replacementAt(text, edit.range, edit.newText))
    .sort((a, b) => b.start - a.start);

  let result = text;
  for (const { start, end, text: value } of replacements) {
    result = result.slice(0, start) + value + result.slice(end);
  }
  return result;
}

/** 按文件分组 LSP 工作区编辑 (忽略非 `file:` 协议的目标) */
export function renameFileEdits(edit: LspWorkspaceEdit): RenameFileEdit[] {
  return Object.entries(edit.changes ?? {})
    .filter(([uri]) => uri.startsWith('file://'))
    .map(([uri, edits]) => ({ path: fromUri(uri), edits }));
}
